#include <cuda_runtime.h>
#include <cstdio>
#include <cstdint>
#include <vector>
#include <cstring>
#include <string>
#include <chrono>
#include "corrected_kernels.h"
#define CHECK(x) do{auto e=(x);if(e!=cudaSuccess){fprintf(stderr,"CUDA %s\n",cudaGetErrorString(e));exit(10);}}while(0)
struct Case{int w,h,n;float3*rgb;uint*tmp,*out;};
int main(){static_assert(sizeof(float3)==12);std::vector<uint32_t>prefix(9998),gold(17200);FILE*f=fopen("/home/imo/HeCBench_julia/src/depixel-julia/fixture.bin","rb");if(!f||fread(prefix.data(),4,prefix.size(),f)!=prefix.size())return 4;fclose(f);f=fopen("/home/imo/HeCBench_julia/src/depixel-julia/oracle.bin","rb");if(!f||fread(gold.data(),4,gold.size(),f)!=gold.size())return 5;fclose(f);std::vector<Case>cases;int offset=0;for(int ci=0;ci<7;ci++){Case c;c.w=prefix[9984+2*ci];c.h=prefix[9984+2*ci+1];c.n=c.w*c.h;std::vector<float3>rgb(c.n+16,make_float3(-12345.f,-12345.f,-12345.f));memcpy(rgb.data()+8,prefix.data()+offset,3*c.n*4);offset+=3*c.n;CHECK(cudaMalloc(&c.rgb,rgb.size()*12));CHECK(cudaMemcpy(c.rgb,rgb.data(),rgb.size()*12,cudaMemcpyHostToDevice));CHECK(cudaMalloc(&c.tmp,(c.n+16)*4));CHECK(cudaMalloc(&c.out,(c.n+16)*4));cases.push_back(c);}if(offset!=9984)return 6;
auto launch=[](Case&c){check_connect<<<c.n/256,256>>>(c.rgb+8,c.tmp+8,c.w,c.h);eliminate_crosses<<<c.n/256,256>>>(c.tmp+8,c.out+8,c.w,c.h);};for(auto&c:cases){launch(c);CHECK(cudaDeviceSynchronize());}
for(int trial=1;trial<=5;trial++){bool ok=true;double seconds=0;std::vector<double>path_times;std::vector<uint32_t>art=prefix;for(auto&c:cases){std::vector<uint>reset(c.n+16,0xfedcba98);CHECK(cudaMemcpy(c.tmp,reset.data(),reset.size()*4,cudaMemcpyHostToDevice));CHECK(cudaMemcpy(c.out,reset.data(),reset.size()*4,cudaMemcpyHostToDevice));auto t=std::chrono::steady_clock::now();for(int rep=0;rep<100;rep++)launch(c);CHECK(cudaDeviceSynchronize());double dt=std::chrono::duration<double>(std::chrono::steady_clock::now()-t).count()/100;seconds+=dt;path_times.push_back(dt);for(uint*ptr:{c.tmp,c.out}){CHECK(cudaMemcpy(reset.data(),ptr,reset.size()*4,cudaMemcpyDeviceToHost));art.insert(art.end(),reset.begin(),reset.end());}std::vector<uint32_t>echo(3*c.n+48);CHECK(cudaMemcpy(echo.data(),c.rgb,echo.size()*4,cudaMemcpyDeviceToHost));art.insert(art.end(),echo.begin(),echo.end());}if(art.size()!=27198)return 7;for(int i=0;i<17200;i++)ok&=art[9998+i]==gold[i];std::string path=std::string(getenv("STUDY_OUTPUT_DIR")?getenv("STUDY_OUTPUT_DIR"):".")+"/output_trial"+std::to_string(trial)+".bin";FILE*out=fopen(path.c_str(),"wb");fwrite(art.data(),4,art.size(),out);fclose(out);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":17200,\"max_abs_error\":0,\"max_rel_error\":0,\"timing_region\":\"sum7_connect_crossgraph_two_kernel_batches_per_repeat\",\"jit_excluded\":true,\"internal_repeats\":100,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"uint32\",\"count\":27198,\"byte_order\":\"little\"},\"path_times_seconds\":[",trial,seconds,ok?"true":"false",path.c_str(),art.size());for(int i=0;i<7;i++)printf("%s%.17g",i?",":"",path_times[i]);printf("]}\n");}for(auto&c:cases){cudaFree(c.rgb);cudaFree(c.tmp);cudaFree(c.out);}}
